test('invoiceTotals with tier discount applied', () => {
  const result = createInvoice({
    customerId: 'C-001', // gold tier (5%)
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
    ],
  });
  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  const subtotal = 2 * 8500; // 17000
  const discount = Math.floor(subtotal * 5 / 100); // 850
  const afterDiscount = subtotal - discount; // 16150
  const vat = Math.round(afterDiscount * 21 / 100); // 3392
  const total = afterDiscount + vat; // 19542

  assert.equal(totals.subtotal, 17000);
  assert.equal(totals.discount, 850);
  assert.equal(totals.vat, 3392);
  assert.equal(totals.total, 19542);
});

test('invoiceTotals with mixed tier and line discounts', () => {
  const result = createInvoice({
    customerId: 'C-003', // silver tier (2.5%)
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2, discountPercent: 10 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  });
  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  const line1Total = 2 * 8500; // 17000
  const line1Discount = Math.floor(line1Total * 10 / 100); // 1700
  const line1AfterDiscount = line1Total - line1Discount; // 15300
  const line1Vat = Math.round(line1AfterDiscount * 21 / 100); // 3213
  const line2Total = 3 * 9500; // 28500
  const line2Discount = Math.floor(line2Total * 2.5 / 100); // 712
  const line2AfterDiscount = line2Total - line2Discount; // 27788
  const line2Vat = Math.round(line2AfterDiscount * 21 / 100); // 5835
  const subtotal = line1Total + line2Total; // 45500
  const totalDiscount = line1Discount + line2Discount; // 2412
  const totalVat = line1Vat + line2Vat; // 9048
  const total = subtotal - totalDiscount + totalVat; // 52136

  assert.equal(totals.subtotal, 45500);
  assert.equal(totals.discount, 2412);
  assert.equal(totals.vat, 9048);
  assert.equal(totals.total, 52136);
});

