test('invoiceTotals calculates VAT on amount after discount', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 20, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const lineTotal = 10 * 1000; // 10000
  const discount = Math.floor(lineTotal * 20 / 100); // 2000
  const amountAfterDiscount = lineTotal - discount; // 8000
  const expectedVat = Math.round(amountAfterDiscount * 21 / 100); // 1680

  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 2000);
  assert.equal(totals.vat, 1680);
  assert.equal(totals.total, 10000 - 2000 + 1680); // 9680
});

