    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const invoice = result.value;
  const baseTotals = invoiceTotals(invoice);

  const vouchered = applyVoucher(invoice, { code: 'TEST', amount: 3000 }).value;
  const voucherTotals = invoiceTotals(vouchered);

  assert.equal(voucherTotals.subtotal, baseTotals.subtotal);
  assert.equal(voucherTotals.discount, baseTotals.discount);
  assert.equal(voucherTotals.vat, baseTotals.vat);
  assert.equal(voucherTotals.voucher, 3000);
  assert.equal(voucherTotals.total, baseTotals.total - 3000);
});

test('invoiceTotals with multiple components including voucher', () => {
  const result = createInvoice({
    customerId: 'C-001', // gold tier (5% discount)
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: 10 }],
  });
  const invoice = result.value;
  const vouchered = applyVoucher(invoice, { code: 'FLAT50', amount: 5000 }).value;

  const totals = invoiceTotals(vouchered);
  const subtotal = 2 * 8500; // 17000
  const lineDiscount = Math.floor(subtotal * 10 / 100); // 1700
  const afterDiscount = subtotal - lineDiscount; // 15300
  const vat = Math.round(afterDiscount * 21 / 100); // 3213
  const beforeVoucher = subtotal - lineDiscount + vat; // 18513
  const afterVoucher = beforeVoucher - 5000; // 13513

  assert.equal(totals.subtotal, 17000);
  assert.equal(totals.discount, 1700);
  assert.equal(totals.vat, 3213);
  assert.equal(totals.voucher, 5000);
  assert.equal(totals.total, 13513);
});

