import test from 'node:test';
import assert from 'node:assert/strict';
import { overdueInvoices } from '../src/reports.js';
import { createInvoice, issueInvoice, invoiceTotals } from '../src/invoices.js';

test('overdueInvoices returns empty array when no invoices', () => {
  const result = overdueInvoices([], '2026-10-15');
  assert.deepEqual(result, []);
});

test('overdueInvoices returns empty array when no overdue invoices', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET30',
  });
  assert.equal(result.ok, true);
  const invoice = result.value;
  const issued = issueInvoice(invoice, []);
  assert.equal(issued.ok, true);

  const overdue = overdueInvoices([issued.value], '2026-11-06');
  assert.equal(overdue.length, 0);
});

test('overdueInvoices includes invoice with dueDate before asOf', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'NET14',
  });
  const invoice = result.value;
  const issued = issueInvoice(invoice, []);
  const issuedInvoice = issued.value;

  const overdue = overdueInvoices([issuedInvoice], '2026-10-22');
  assert.equal(overdue.length, 1);
  assert.equal(overdue[0].number, 'INV-2026-0001');
  assert.equal(overdue[0].customerId, 'C-001');
  assert.equal(overdue[0].dueDate, '2026-10-21');
});

test('overdueInvoices calculates daysOverdue correctly', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET7',
  });
  assert.equal(result.ok, true);
  const invoice = result.value;
  const issued = issueInvoice(invoice, []);
  assert.equal(issued.ok, true);
  const issuedInvoice = issued.value;

  const overdue = overdueInvoices([issuedInvoice], '2026-10-15');
  assert.equal(overdue[0].daysOverdue, 7);
});

test('overdueInvoices calculates due using invoiceTotals', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'NET14',
  });
  const invoice = result.value;
  const totals = invoiceTotals(invoice);
  const issued = issueInvoice(invoice, []);
  const issuedInvoice = issued.value;

  const overdue = overdueInvoices([issuedInvoice], '2026-10-22');
  assert.equal(overdue[0].due, totals.total);
});

test('overdueInvoices excludes draft status invoices', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  const invoice = result.value;

  const overdue = overdueInvoices([invoice], '2026-10-22');
  assert.equal(overdue.length, 0);
});

test('overdueInvoices includes issued status invoices', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  const invoice = result.value;
  const issued = issueInvoice(invoice, []);
  const issuedInvoice = issued.value;

  const overdue = overdueInvoices([issuedInvoice], '2026-10-22');
  assert.equal(overdue.length, 1);
});

test('overdueInvoices includes partially_paid status invoices', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  const invoice = result.value;
  const issued = issueInvoice(invoice, []);
  const partiallyPaidInvoice = { ...issued.value, status: 'partially_paid' };

  const overdue = overdueInvoices([partiallyPaidInvoice], '2026-10-22');
  assert.equal(overdue.length, 1);
});

test('overdueInvoices excludes other status invoices', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  const invoice = result.value;
  const issued = issueInvoice(invoice, []);
  const paidInvoice = { ...issued.value, status: 'paid' };

  const overdue = overdueInvoices([paidInvoice], '2026-10-22');
  assert.equal(overdue.length, 0);
});

test('overdueInvoices sorts by daysOverdue descending (most overdue first)', () => {
  const result1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET7',
  });
  assert.equal(result1.ok, true);
  const issued1 = issueInvoice(result1.value, []);
  assert.equal(issued1.ok, true);

  const result2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-05',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET7',
  });
  assert.equal(result2.ok, true);
  const issued2 = issueInvoice(result2.value, ['INV-2026-0001']);
  assert.equal(issued2.ok, true);

  const result3 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET7',
  });
  assert.equal(result3.ok, true);
  const issued3 = issueInvoice(result3.value, ['INV-2026-0001', 'INV-2026-0002']);
  assert.equal(issued3.ok, true);

  const overdue = overdueInvoices(
    [issued3.value, issued2.value, issued1.value],
    '2026-10-20'
  );

  assert.equal(overdue.length, 3);
  assert.equal(overdue[0].daysOverdue, 13);
  assert.equal(overdue[1].daysOverdue, 9);
  assert.equal(overdue[2].daysOverdue, 6);
});

