  assert.equal(overdue.length, 2);
  assert.equal(overdue[0].number, 'INV-2026-0001');
  assert.equal(overdue[1].number, 'INV-2026-0002');
});

test('overdueInvoices includes necessary properties in result', () => {
  const result = createInvoice({
    customerId: 'C-001',
