    terms: 'NET14',
  });
  assert.equal(result1.ok, true);
  const issued1 = issueInvoice(result1.value, []);
  assert.equal(issued1.ok, true);

  const result2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-05',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  assert.equal(result2.ok, true);
  const issued2 = issueInvoice(result2.value, ['INV-2026-0001']);
  assert.equal(issued2.ok, true);

