  assert.equal(issued2.ok, true);

  const result3 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-03',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  assert.equal(result3.ok, true);

  const partiallyPaid = { ...issued2.value, status: 'partially_paid' };

  const overdue = overdueInvoices(
    [issued1.value, partiallyPaid, result3.value],
    '2026-10-20'
  );

  assert.equal(overdue.length, 2);
  assert.equal(overdue[0].number, 'INV-2026-0001');
  assert.equal(overdue[1].number, 'INV-2026-0002');
});

test('overdueInvoices includes necessary properties in result', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
